shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  porcelain : vec3<f32>,
  cobalt : vec3<f32>,
  pearl : vec3<f32>,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) normal : vec3<f32>,
  @location(2) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vNormal : vec3<f32>,
  @location(1) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vNormal = in.normal;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let n = normalize(in.vNormal);
  let veinA = abs(sin(((in.vUv.x * 29.0) + (sin((in.vUv.y * 17.0)) * 1.8))));
  let veinB = abs(sin(((in.vUv.y * 37.0) + (sin((in.vUv.x * 11.0)) * 2.1))));
  let crackle = smoothstep(0.08, 0.015, (veinA * veinB));
  let wash = ((sin(((in.vUv.x - in.vUv.y) * 8.0)) * 0.06) + 0.1);
  let body = mix(u.porcelain.rgb, u.cobalt.rgb, ((crackle * 0.62) + wash));
  let rim = (pow((1.0 - abs(n.z)), 3.0) * 0.24);
  return vec4<f32>(mix(body, u.pearl.rgb, rim), 1.0);
}

shaders.vertex:
#version 300 es
in vec3 position;
in vec3 normal;
in vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 porcelain;
uniform vec3 cobalt;
uniform vec3 pearl;
out vec3 vNormal;
out vec2 vUv;

void main() {
  vNormal = normal;
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 porcelain;
uniform vec3 cobalt;
uniform vec3 pearl;
in vec3 vNormal;
in vec2 vUv;
out vec4 fragColor;

void main() {
  vec3 n = normalize(vNormal);
  float veinA = abs(sin(((vUv.x * 29.0) + (sin((vUv.y * 17.0)) * 1.8))));
  float veinB = abs(sin(((vUv.y * 37.0) + (sin((vUv.x * 11.0)) * 2.1))));
  float crackle = smoothstep(0.08, 0.015, (veinA * veinB));
  float wash = ((sin(((vUv.x - vUv.y) * 8.0)) * 0.06) + 0.1);
  vec3 body = mix(porcelain.rgb, cobalt.rgb, ((crackle * 0.62) + wash));
  float rim = (pow((1.0 - abs(n.z)), 3.0) * 0.24);
  fragColor = vec4(mix(body, pearl.rgb, rim), 1.0);
}
